CREATE POLICY "Listing media is readable by everyone" ON storage.objects FOR SELECT USING (bucket_id = 'listing-media');
CREATE POLICY "Users can upload their own listing media" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'listing-media' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users can update their own listing media" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'listing-media' AND auth.uid()::text = (storage.foldername(name))[1]);
CREATE POLICY "Users can delete their own listing media" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'listing-media' AND auth.uid()::text = (storage.foldername(name))[1]);